pic\", \"MiniMax\", \"OpenAI\", \"Stepfun\", \"DeepSeek\", \"Zhipu\", \"x-ai\", \"Others\"],\n  values: [25.9, 11.8, 11.0, 8.5, 7.9, 6.8, 6.6, 6.5, 3.9, 11.2]\n}], {\n  x: 0.3, y: 1.3, w: 5.2, h: 4.0,\n  showPercent: true,\n  showLegend: true,\n  legendPos: \"b\",\n  legendFontSize: 9,\n  chartColors: [\"065A82\", \"1C7293\", \"14B8A6\", \"5EEAD4\", \"94A3B8\", \"0891B2\", \"06B6D4\", \"67E8F9\", \"334155\", \"CBD5E1\"],\n  dataLabelColor: C.darkText,\n  dataLabelFontSize: 9\n});\n\n// Key insights card on the right\nslide3.addShape(pres.shapes.RECTANGLE, {\n  x: 5.8, y: 1.3, w: 3.9, h: 3.8,\n  fill: { color: C.white },\n  shadow: { type: \"outer\", color: \"000000\", blur: 8, offset: 2, angle: 135, opacity: 0.08 }\n});\n\nslide3.addText(\"Key Insights\", {\n  x: 6.1, y: 1.5, w: 3.4, h: 0.4,\n  fontFace: TITLE_FONT, fontSize: 16, color: C.deepBlue, bold: true\n});\n\nslide3.addText([\n  { text: \"Xiaomi leads at 25.9%\", options: { bold: true, breakLine: true } },\n  { text: \"More than double 2nd-place Google\", options: { fontSize: 10, color: C.midGray, breakLine: true } },\n  { text: \"\", options: { breakLine: true, fontSize: 8 } },\n  { text: \"Chinese providers: 54.3%\", options: { bold: true, breakLine: true } },\n  { text: \"Xiaomi + MiniMax + Stepfun + DeepSeek + Zhipu combined\", options: { fontSize: 10, color: C.midGray, breakLine: true } },\n  { text: \"\", options: { breakLine: true, fontSize: 8 } },\n  { text: \"OpenAI ranks only 5th (7.9%)\", options: { bold: true, breakLine: true } },\n  { text: \"Highly fragmented market — no single provider exceeds 30%\", options: { fontSize: 10, color: C.midGray } }\n], {\n  x: 6.1, y: 1.95, w: 3.4, h: 2.9,\n  fontFace: BODY_FONT, fontSize: 12, color: C.darkText, valign: \"top\"\n});\n\n// ========== SLIDE 4: Shifts in the Market Landscape ==========\nconst slide4 = pres.addSlide();\nslide4.background = { color: C.offWhite };\n\nslide4.addText(\"Shifts in the Market Landscape\", {\n  x: 0.5, y: 0.3, w: 9, h: 0.7,\n  fontFace: TITLE_FONT, fontSize: 36, color: C.darkText, bold: true, margin: 0\n});\n\nslide4.addText(\"Key competitive dynamics shaping the LLM market (March 2025)\", {\n  x: 0.5, y: 0.9, w: 7, h: 0.35,\n  fontFace: BODY_FONT, fontSize: 12, color: C.midGray\n});\n\n// Three insight cards\nconst cardData = [\n  {\n    title: \"Chinese Models Break Through\",\n    body: \"6 of top 10 models from Chinese providers. Combined share exceeds 54% on this international platform.\",\n    stat: \"54.3%\",\n    statLabel: \"Chinese provider share\"\n  },\n  {\n    title: \"Flash/Turbo Dominates Usage\",\n    body: \"Step 3.5 Flash, GLM 5 Turbo, Gemini 3 Flash — speed and cost outweigh peak performance in real-world usage.\",\n    stat: \"3 of 10\",\n    statLabel: \"Top models are Flash variants\"\n  },\n  {\n    title: \"Market Growth & Fragmentation\",\n    body: \"Weekly usage grew from ~2T to ~26T tokens (13x). Yet the top 10 spans 8 providers — no monopoly in sight.\",\n    stat: \"13x\",\n    statLabel: \"Weekly token growth\"\n  }\n];\n\ncardData.forEach((card, i) => {\n  const xPos = 0.5 + i * 3.1;\n\n  slide4.addShape(pres.shapes.RECTANGLE, {\n    x: xPos, y: 1.4, w: 2.9, h: 3.9,\n    fill: { color: C.white },\n    shadow: { type: \"outer\", color: \"000000\", blur: 6, offset: 2, angle: 135, opacity: 0.08 }\n  });\n\n  // Stat callout\n  slide4.addText(card.stat, {\n    x: xPos + 0.2, y: 1.6, w: 2.5, h: 0.7,\n    fontFace: TITLE_FONT, fontSize: 32, color: C.deepBlue, bold: true, margin: 0\n  });\n\n  slide4.addText(card.statLabel, {\n    x: xPos + 0.2, y: 2.25, w: 2.5, h: 0.3,\n    fontFace: BODY_FONT, fontSize: 10, color: C.midGray, margin: 0\n  });\n\n  // Divider\n  slide4.addShape(pres.shapes.RECTANGLE, {\n    x: xPos + 0.2, y: 2.65, w: 1.2, h: 0.03,\n    fill: { color: C.accent }\n  });\n\n  slide4.addText(card.title, {\n    x: xPos + 0.2, y: 2.8, w: 2.5, h: 0.5,\n    fontFace: TITLE_FONT, fontSize: 13, color: C.darkText, bold: true, margin: 0\n  });\n\n  slide4.addText(card.body, {\n    x: xPos + 0.2, y: 3.3, w: 2.5, h: 1.8,\n    fontFace: BODY_FONT, fontSize: 11, color: C.midGray, valign: \"top\", margin: 0\n  });\n});\n\n// Anthropic note at bottom\nslide4.addText(\"Note: Anthropic maintains two models in top 10 (combined ~2T tokens), but growth has stalled at -0% and +2% WoW.\", {\n  x: 0.5, y: 5.2, w: 9, h: 0.3,\n  fontFace: BODY_FONT, fontSize: 10, color: C.midGray, italic: true\n});\n\n// ========== SLIDE 5: Rising Stars ==========\nconst slide5 = pres.addSlide();\nslide5.background = { color: C.offWhite };\n\nslide5.addText(\"This Week's Rising Stars: Fastest-Growing Models\", {\n  x: 0.5, y: 0.3, w: 9, h: 0.7,\n  fontFace: TITLE_FONT, fontSize: 34, color: C.darkText, bold: true, margin: 0\n});\n\nslide5.addText(\"Models with the highest week-over-week growth in token usage\", {\n  x: 0.5, y: 0.9, w: 7, h: 0.35,\n  fontFace: BODY_FONT, fontSize: 12, color: C.midGray\n});\n\n// Bar chart for rising stars\nslide5.addChart(pres.charts.BAR, [{\n  name: \"WoW Growth %\",\n  labels: [\"Ampere\", \"MiniMax M2.7\", \"MiMo-V2-Pro\", \"Cline\", \"Codex\", \"Hermes Agent\"],\n  values: [576, 253, 165, 128, 112, 92]\n}], {\n  x: 0.5, y: 1.4, w: 5.5, h: 3.8,\n  barDir: \"bar\",\n  chartColors: [\"14B8A6\"],\n  chartArea: { fill: { color: C.white }, roundedCorners: true },\n  catAxisLabelColor: C.darkText,\n  catAxisLabelFontSize: 11,\n  valAxisLabelColor: C.midGray,\n  valGridLine: { color: C.lightGray, size: 0.5 },\n  catGridLine: { style: \"none\" },\n  showValue: true,\n  dataLabelPosition: \"outEnd\",\n  dataLabelColor: C.darkText,\n  dataLabelFontSize: 10,\n  showLegend: false,\n  valAxisTitle: \"Week-over-Week Growth (%)\"\n});\n\n// Insight panel on right\nslide5.addShape(pres.shapes.RECTANGLE, {\n  x: 6.3, y: 1.4, w: 3.4, h: 3.8,\n  fill: { color: C.white },\n  shadow: { type: \"outer\", color: \"000000\", blur: 6, offset: 2, angle: 135, opacity: 0.08 }\n});\n\nslide5.addText(\"Growth Drivers\", {\n  x: 6.5, y: 1.6, w: 3.0, h: 0.4,\n  fontFace: TITLE_FONT, fontSize: 16, color: C.deepBlue, bold: true\n});\n\nslide5.addText([\n  { text: \"MiniMax M2.7 (+253%)\", options: { bold: true, breakLine: true } },\n  { text: \"New model launch with strong cost-performance ratio\", options: { fontSize: 10, color: C.midGray, breakLine: true } },\n  { text: \"\", options: { breakLine: true, fontSize: 6 } },\n  { text: \"MiMo-V2-Pro (+165%)\", options: { bold: true, breakLine: true } },\n  { text: \"Xiaomi's flagship riding demand for affordable Chinese models\", options: { fontSize: 10, color: C.midGray, breakLine: true } },\n  { text: \"\", options: { breakLine: true, fontSize: 6 } },\n  { text: \"Cline (+128%)\", options: { bold: true, breakLine: true } },\n  { text: \"Independent AI coding agent gaining traction in dev community\", options: { fontSize: 10, color: C.midGray, breakLine: true } },\n  { text: \"\", options: { breakLine: true, fontSize: 6 } },\n  { text: \"Codex (+112%)\", options: { bold: true, breakLine: true } },\n  { text: \"OpenAI's coding model benefiting from agent tool ecosystem\", options: { fontSize: 10, color: C.midGray } }\n], {\n  x: 6.5, y: 2.1, w: 3.0, h: 2.9,\n  fontFace: BODY_FONT, fontSize: 12, color: C.darkText, valign: \"top\"\n});\n\n// ========== SLIDE 6: App Ecosystem ==========\nconst slide6 = pres.addSlide();\nslide6.background = { color: C.offWhite };\n\nslide6.addText(\"App Ecosystem: Who's Calling These Models\", {\n  x: 0.5, y: 0.3, w: 9, h: 0.7,\n  fontFace: TITLE_FONT, fontSize: 34, color: C.darkText, bold: true, margin: 0\n});\n\nslide6.addText(\"Top apps by daily token consumption on OpenRouter\", {\n  x: 0.5, y: 0.9, w: 7, h: 0.35,\n  fontFace: BODY_FONT, fontSize: 12, color: C.midGray\n});\n\n// Bar chart for top apps\nslide6.addChart(pres.charts.BAR, [{\n  name: \"Daily Tokens (Billions)\",\n  labels: [\"OpenClaw\", \"Kilo Code\", \"Claude Code\", \"Cline\", \"Janitor AI\", \"ISEKAI ZERO\", \"Descript\", \"Hermes Agent\", \"Roo Code\", \"Scripty\"],\n  values: [829, 271, 78, 69.1, 29.2, 28.8, 27, 19.2, 11.8, 9.95]\n}], {\n  x: 0.3, y: 1.3, w: 6.0, h: 4.0,\n  barDir: \"bar\",\n  chartColors: [\"065A82\"],\n  chartArea: { fill: { color: C.white }, roundedCorners: true },\n  catAxisLabelColor: C.darkText,\n  catAxisLabelFontSize: 10,\n  valAxisLabelColor: C.midGray,\n  valGridLine: { color: C.lightGray, size: 0.5 },\n  catGridLine: { style: \"none\" },\n  showValue: true,\n  dataLabelPosition: \"outEnd\",\n  dataLabelColor: C.darkText,\n  dataLabelFontSize: 9,\n  showLegend: false\n});\n\n// Insight card\nslide6.addShape(pres.shapes.RECTANGLE, {\n  x: 6.5, y: 1.3, w: 3.2, h: 4.0,\n  fill: { color: C.white },\n  shadow: { type: \"outer\", color: \"000000\", blur: 6, offset: 2, angle: 135, opacity: 0.08 }\n});\n\nslide6.addText(\"Key Takeaway\", {\n  x: 6.7, y: 1.5, w: 2.8, h: 0.4,\n  fontFace: TITLE_FONT, fontSize: 16, color: C.deepBlue, bold: true\n});\n\nslide6.addText([\n  { text: \"AI Coding Tools Dominate\", options: { bold: true, fontSize: 13, breakLine: true } },\n  { text: \"\", options: { breakLine: true, fontSize: 6 } },\n  { text: \"Top 4 apps are all coding tools:\", options: { breakLine: true } },\n  { text: \"OpenClaw, Kilo Code, Claude Code, Cline\", options: { bold: true, breakLine: true } },\n  { text: \"\", options: { breakLine: true, fontSize: 6 } },\n  { text: \"5 of the top 10 apps are coding-related — making code generation the single largest LLM consumption scenario.\", options: { breakLine: true } },\n  { text: \"\", options: { breakLine: true, fontSize: 6 } },\n  { text: \"OpenClaw alone: 829B tokens/day\", options: { bold: true, color: C.deepBlue, breakLine: true } },\n  { text: \"Nearly 3x the second-place app\", options: { fontSize: 10, color: C.midGray, breakLine: true } },\n  { text: \"\", options: { breakLine: true, fontSize: 6 } },\n  { text: \"Entertainment (Janitor AI, ISEKAI ZERO) retains a notable presence among non-coding categories.\", options: { fontSize: 10, color: C.midGray } }\n], {\n  x: 6.7, y: 1.95, w: 2.8, h: 3.1,\n  fontFace: BODY_FONT, fontSize: 11, color: C.darkText, valign: \"top\"\n});\n\n// ========== SLIDE 7: Key Insights and Industry Implications ==========\nconst slide7 = pres.addSlide();\nslide7.background = { color: C.darkBg };\n\nslide7.addText(\"Key Insights and Industry Implications\", {\n  x: 0.5, y: 0.3, w: 9, h: 0.7,\n  fontFace: TITLE_FONT, fontSize: 36, color: C.white, bold: true, margin: 0\n});\n\n// Four key takeaway cards in 2x2 grid\nconst takeaways = [\n  {\n    num: \"01\",\n    title: \"Chinese Models Hold Dominant Global Share\",\n    body: \"Over 54% of token usage from Chinese providers (Xiaomi, MiniMax, Stepfun, DeepSeek, Zhipu) on an international platform.\"\n  },\n  {\n    num: \"02\",\n    title: \"AI Coding Agents = Largest Consumption Scenario\",\n    body: \"5 of top 10 apps are coding tools. Code generation is now the primary commercial value proposition for LLMs.\"\n  },\n  {\n    num: \"03\",\n    title: \"Highly Fragmented Market, No Outright Winner\",\n    body: \"Top 10 models span 8 providers. No single provider exceeds 30% share. Competition remains fierce.\"\n  },\n  {\n    num: \"04\",\n    title: \"Flash/Turbo Variants Outpace Flagship Models\",\n    body: \"Users choose speed + cost over peak capability. Affordable models consistently see higher adoption in real-world use.\"\n  }\n];\n\ntakeaways.forEach((item, i) => {\n  const col = i % 2;\n  const row = Math.floor(i / 2);\n  const xPos = 0.5 + col * 4.7;\n  const yPos = 1.2 + row * 2.1;\n\n  slide7.addShape(pres.shapes.RECTANGLE, {\n    x: xPos, y: yPos, w: 4.4, h: 1.9,\n    fill: { color: C.navy },\n    shadow: { type: \"outer\", color: \"000000\", blur: 4, offset: 1, angle: 135, opacity: 0.2 }\n  });\n\n  // Accent bar on left\n  slide7.addShape(pres.shapes.RECTANGLE, {\n    x: xPos, y: yPos, w: 0.06, h: 1.9,\n    fill: { color: C.accent }\n  });\n\n  slide7.addText(item.num, {\n    x: xPos + 0.25, y: yPos + 0.15, w: 0.5, h: 0.35,\n    fontFace: TITLE_FONT, fontSize: 18, color: C.accent, bold: true, margin: 0\n  });\n\n  slide7.addText(item.title, {\n    x: xPos + 0.25, y: yPos + 0.45, w: 3.9, h: 0.5,\n    fontFace: TITLE_FONT, fontSize: 13, color: C.white, bold: true, margin: 0\n  });\n\n  slide7.addText(item.body, {\n    x: xPos + 0.25, y: yPos + 0.95, w: 3.9, h: 0.8,\n    fontFace: BODY_FONT, fontSize: 10.5, color: C.lightGray, valign: \"top\", margin: 0\n  });\n});\n\n// Footer\nslide7.addText(\"Source: OpenRouter Rankings (March 2025)  |  Data reflects real-world usage from millions of users\", {\n  x: 0.5, y: 5.2, w: 9, h: 0.3,\n  fontFace: BODY_FONT, fontSize: 10, color: C.midGray, italic: true\n});\n\n// Write file\npres.writeFile({ fileName: \"/app/output/final_deck.pptx\" })\n  .then(() => console.log(\"SUCCESS: Presentation saved to /app/output/final_deck.pptx\"))\n  .catch(err => console.error(\"ERROR:\", err));\n", "numLines": 523, "startLine": 1, "totalLines": 523}}

