const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Data Analysis Team";
pres.title = "The 2025 LLM Usage Landscape: Real-World Data from OpenRouter";

// Color palette - Ocean Gradient / Deep Tech
const C = {
  darkBg: "0A1628",
  navy: "0F2340",
  deepBlue: "065A82",
  teal: "1C7293",
  accent: "14B8A6",
  lightAccent: "5EEAD4",
  white: "FFFFFF",
  offWhite: "F0F9FF",
  lightGray: "E2E8F0",
  midGray: "64748B",
  darkText: "1E293B",
  cardBg: "F8FAFC",
};

// Fonts
const TITLE_FONT = "Trebuchet MS";
const BODY_FONT = "Calibri";

// ========== SLIDE 1: Title Slide ==========
const slide1 = pres.addSlide();
slide1.background = { color: C.darkBg };

// Decorative shapes
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 5.625,
  fill: { color: C.navy, transparency: 40 }
});
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 4.8, w: 10, h: 0.825,
  fill: { color: C.deepBlue, transparency: 60 }
});
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.2, w: 0.06, h: 2.4,
  fill: { color: C.accent }
});

slide1.addText("The 2025 LLM Usage Landscape:\nReal-World Data from OpenRouter", {
  x: 0.9, y: 1.2, w: 8.5, h: 2.4,
  fontFace: TITLE_FONT, fontSize: 38, color: C.white, bold: true,
  lineSpacingMultiple: 1.3, valign: "middle", margin: 0
});

slide1.addText("Data Source: OpenRouter Rankings  |  Latest Week of March 2025", {
  x: 0.9, y: 3.7, w: 6, h: 0.4,
  fontFace: BODY_FONT, fontSize: 14, color: C.lightAccent, italic: true
});

slide1.addText([
  { text: "26T+", options: { fontSize: 52, bold: true, color: C.accent } },
  { text: "  tokens processed this week", options: { fontSize: 16, color: C.midGray } }
], {
  x: 0.9, y: 4.3, w: 6, h: 0.9, valign: "middle", margin: 0
});

slide1.addText("Millions of users  •  Real-world usage patterns  •  Competitive intelligence", {
  x: 0.9, y: 5.1, w: 8, h: 0.35,
  fontFace: BODY_FONT, fontSize: 11, color: C.midGray
});

// ========== SLIDE 2: Top 10 Models (Table) ==========
const slide2 = pres.addSlide();
slide2.background = { color: C.offWhite };

slide2.addText("This Week's Top 10 Models", {
  x: 0.5, y: 0.3, w: 9, h: 0.7,
  fontFace: TITLE_FONT, fontSize: 36, color: C.darkText, bold: true, margin: 0
});

slide2.addText("Ranked by weekly token usage on OpenRouter (March 2025)", {
  x: 0.5, y: 0.9, w: 6, h: 0.35,
  fontFace: BODY_FONT, fontSize: 12, color: C.midGray
});

const headerOpts = { bold: true, color: C.white, fill: { color: C.deepBlue }, align: "center", valign: "middle" };
const cellOpts = { color: C.darkText, valign: "middle" };
const cellCenter = { color: C.darkText, align: "center", valign: "middle" };

const tableRows = [
  [
    { text: "#", options: headerOpts },
    { text: "Model", options: { ...headerOpts, align: "left" } },
    { text: "Provider", options: { ...headerOpts, align: "left" } },
    { text: "Weekly Tokens", options: headerOpts },
    { text: "WoW Change", options: headerOpts }
  ],
  [
    { text: "1", options: { ...cellCenter, fill: { color: "DBEAFE" } } },
    { text: "MiMo-V2-Pro", options: { ...cellOpts, bold: true, fill: { color: "DBEAFE" } } },
    { text: "Xiaomi", options: { ...cellOpts, fill: { color: "DBEAFE" } } },
    { text: "3.96T", options: { ...cellCenter, bold: true, fill: { color: "DBEAFE" } } },
    { text: "+165%", options: { ...cellCenter, color: "059669", bold: true, fill: { color: "DBEAFE" } } }
  ],
  [
    { text: "2", options: cellCenter },
    { text: "Step 3.5 Flash (free)", options: cellOpts },
