const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Data Analysis Team";
pres.title = "The 2025 LLM Usage Landscape: Real-World Data from OpenRouter";

// Color palette - Ocean Gradient / Deep Tech
const C = {
  darkBg: "0A1628",
  navy: "0F2340",
  deepBlue: "065A82",
  teal: "1C7293",
  accent: "14B8A6",
  lightAccent: "5EEAD4",
  white: "FFFFFF",
  offWhite: "F0F9FF",
  lightGray: "E2E8F0",
  midGray: "64748B",
  darkText: "1E293B",
  cardBg: "F8FAFC",
};

// Fonts
